                  <path fill="currentColor" fillOpacity=".5" d="m77.48,65.08c-.27,6.71-5.87,12.21-12.58,12.38-2.35.06-4.55-.51-6.47-1.55l91.86,50.55V51.64h-85.71c7.31,0,13.2,6.07,12.91,13.44Z"/>
